  goal.seat=reservation.seat;const station=stations.get(goal.stationId);if(!navigate(sim,npc,reservation.position,environment,now,dt,collision,objects,cast,players))return;goal.status='active';info.moving=false;info.lookAt={x:station.position.x,y:1.3,z:station.position.z};
