export function casinoLifeView(sim){const life=sim.casinoLife;if(!life)return null;return {version:2,stats:{...life.stats},conversations:life.conversations.slice(-6).map(c=>({id:c.id,participants:[...c.participants],topic:c.topic,turn:c.turn,status:c.status,startedAt:c.startedAt,nextAt:c.nextAt,lines:c.lines.slice(-3).map(line=>({...line}))})),events:life.events.slice(-12).map(item=>({...item})),reservations:Object.entries(life.reservations).filter(([,items])=>items.length).slice(0,22).map(([stationId,items])=>({stationId,occupants:items.map(item=>item.npcId)})),serviceQueue:{waiting:life.requests.filter(item=>item.status==='queued').length,serving:life.requests.filter(item=>item.status==='serving').length}};}
