  const migrate=npc.resident.intelligenceVersion!==3;initializeResident(npc,source,index,now);if(migrate){for(const id of Object.keys(life.reservations))releaseCasinoReservation(sim,id,npc.id);delete life.navigation[npc.id];const clear=point=>{const floor=grounded(environment,point,collision,sim,objects);return floor&&(!collision?.hasBodyClearance||collision.hasBodyClearance(environment,floor,.4,{actors:sim.actors,objects}))?floor:null;};if(!clear(npc.position)){const candidates=[source.home,...routeNodes].filter(point=>!(Math.abs(point.x)<7.5&&point.z<-22)).map(clear).filter(Boolean).sort((a,b)=>distance(a,npc.position)-distance(b,npc.position));if(candidates[0])npc.position={...candidates[0]};}npc.resident.route=source.route?.map(point=>({...point}));}
